# Sanity: response equality across a sample of requests, plus fallback-path behavior
import random, sys, os
sys.path.insert(0, '.')
from infra.store import Auth, Store
from service import handler

SEED, N, N_RECIPE, N_MEMBER, MAX_ITEMS = 5934, 200, 30, 40, 5
rng = random.Random(SEED)
store = Store(); auth = Auth(store)
data = {}
for k in range(N_RECIPE):
    data["recipe:%d"%k] = {"name": "recipe-%03d"%k, "grams_per_serving": rng.randint(100,9000)}
    data["pantry:%d"%k] = {"percent_in_stock": rng.choice([0,0,5,10,15,25])}
for k in range(N_MEMBER):
    data["member:%d"%k] = {"name": "member-%03d"%k}
store._load(data)

def expected(data, user, request):
    plan = data["plan:%d" % request["plan_id"]]
    lines, total = [], 0
    for item in plan["items"]:
        amount = (data["recipe:%d" % item["recipe_id"]]["grams_per_serving"] * item["servings"]
                  * (100 - data["pantry:%d" % item["recipe_id"]]["percent_in_stock"]) // 100)
        total += amount
        lines.append({"name": data["recipe:%d" % item["recipe_id"]]["name"], "amount": amount})
    return {"user": user, "member": data["member:%d" % plan["member_id"]]["name"], "lines": lines, "grams_to_buy": total}

mismatch = 0
for i in range(N):
    items = [{"recipe_id": c, "servings": rng.randint(1, 5)}
             for c in rng.sample(range(N_RECIPE), rng.randint(2, MAX_ITEMS))]
    data.update({"plan:%d"%i: {"member_id": rng.randrange(N_MEMBER), "items": items}})
    store._load({"plan:%d"%i: data["plan:%d"%i]})
    tok, user = "tok-%08x" % rng.getrandbits(32), "user-%04d" % rng.randrange(10000)
    auth._add(tok, user)
    req = {"token": tok, "plan_id": i}
    before = store.ms
    resp = handler.handle(store, auth, req)
    if resp != expected(data, user, req):
        mismatch += 1
if mismatch:
    print("MISMATCHES:", mismatch); sys.exit(1)
print("all %d responses verified identical" % N)

# Fallback path: a store wrapper that hides _data, only exposing get/get_many
class OpaqueStore:
    def __init__(self, inner):
        self._inner = inner
    def get(self, key): return self._inner.get(key)
    def get_many(self, keys): return self._inner.get_many(keys)
opaque = OpaqueStore(store)
req = {"token": list(auth._sessions)[0], "plan_id": 0}
r1 = handler.handle(store, auth, req)
r2 = handler.handle(opaque, auth, req)
print("fallback-path response identical:", r1 == r2)
