# using the real Store/Auth and the real workload, to ground decisions in data.
import random, math, sys, os
sys.path.insert(0, os.getcwd())
from infra.store import Auth, Store
from bench import (SEED, N_REQUESTS, N_SKU, N_PICKER, MAX_ITEMS, expected)

def build_env():
    rng = random.Random(SEED)
    store = Store(); auth = Auth(store); data = {}
    for k in range(N_SKU):
        data["sku:%d" % k] = {"name": "sku-%03d" % k, "seconds_per_unit": rng.randint(100,9000)}
        data["bin:%d" % k] = {"percent_saved": rng.choice([0,0,5,10,15,25])}
    for k in range(N_PICKER):
        data["picker:%d" % k] = {"name": "picker-%03d" % k}
    store._load(data)
    return rng, store, auth, data

def run(strategy, label):
    rng, store, auth, data = build_env()
    lat=[]
    for i in range(N_REQUESTS):
        items=[{"sku_id":c,"units":rng.randint(1,5)} for c in rng.sample(range(N_SKU), rng.randint(2,MAX_ITEMS))]
        record={"picklist:%d"%i:{"picker_id":rng.randrange(N_PICKER),"items":items}}
        data.update(record); store._load(record)
        token="tok-%08x"%rng.getrandbits(32); user="user-%04d"%rng.randrange(10000)
        auth._add(token,user)
        req={"token":token,"picklist_id":i}
        before=store.ms
        resp=strategy(store,auth,req)
        lat.append(store.ms-before)
        assert resp==expected(data,user,req), label+": wrong response"
    lat.sort(); p95=lat[math.ceil(0.95*len(lat))-1]
    print("%-42s p95=%4d ms  median=%3d  max=%4d  (limit 90)"%(label,p95,lat[len(lat)//2],max(lat)))
    return p95

# Strategy A: original (no caching) - confirm baseline
def original(store,auth,request):
    user=auth.verify(request["token"])
    pl=store.get("picklist:%d"%request["picklist_id"])
    picker=store.get("picker:%d"%pl["picker_id"])
    lines=[]; total=0
    for it in pl["items"]:
        sku=store.get("sku:%d"%it["sku_id"]); binr=store.get("bin:%d"%it["sku_id"])
        amount=sku["seconds_per_unit"]*it["units"]*(100-binr["percent_saved"])//100
        total+=amount; lines.append({"name":sku["name"],"amount":amount})
    return {"user":user,"picker":picker["name"],"lines":lines,"seconds_total":total}

# Strategy B: cache the catalog, still 1 get for picklist + picker, no per-item gets
def cached(store,auth,request,cache):
    user=auth.verify(request["token"])
    pl=store.get("picklist:%d"%request["picklist_id"])
    def getcat(key):
        if key not in cache: cache[key]=store.get(key)
        return cache[key]
    picker=getcat("picker:%d"%pl["picker_id"])
    lines=[]; total=0
    for it in pl["items"]:
        sku=getcat("sku:%d"%it["sku_id"]); binr=getcat("bin:%d"%it["sku_id"])
        amount=sku["seconds_per_unit"]*it["units"]*(100-binr["percent_saved"])//100
        total+=amount; lines.append({"name":sku["name"],"amount":amount})
    return {"user":user,"picker":picker["name"],"lines":lines,"seconds_total":total}

cache={}
