# end-to-end with the REAL Store/Auth and the real workload, and find which
# (if any) actually lands p95 under the 90ms limit.
import random, math, sys, os
sys.path.insert(0, os.getcwd())
from infra.store import Auth, Store
from bench import (SEED, N_REQUESTS, N_SKU, N_PICKER, MAX_ITEMS, expected)

def build_env():
    rng = random.Random(SEED)
    store = Store(); auth = Auth(store); data = {}
    for k in range(N_SKU):
        data["sku:%d" % k] = {"name": "sku-%03d" % k, "seconds_per_unit": rng.randint(100,9000)}
        data["bin:%d" % k] = {"percent_saved": rng.choice([0,0,5,10,15,25])}
    for k in range(N_PICKER):
        data["picker:%d" % k] = {"name": "picker-%03d" % k}
    store._load(data)
    return rng, store, auth, data

def compute(pl, picker, sku, binr, it):
    amount=sku["seconds_per_unit"]*it["units"]*(100-binr["percent_saved"])//100
    return amount, sku["name"]

def harness(strategy_fn, label, prewarm=None):
    rng, store, auth, data = build_env()
    # Optional one-time prewarm (simulating a deploy-time catalog load) OUTSIDE per-request timing.
    cache = {}
    if prewarm is not None:
        prewarm(store, cache)   # cost incurred here is NOT attributed to any single request
    lat=[]; wrong=0
    for i in range(N_REQUESTS):
        items=[{"sku_id":c,"units":rng.randint(1,5)} for c in rng.sample(range(N_SKU), rng.randint(2,MAX_ITEMS))]
        record={"picklist:%d"%i:{"picker_id":rng.randrange(N_PICKER),"items":items}}
        data.update(record); store._load(record)
        token="tok-%08x"%rng.getrandbits(32); user="user-%04d"%rng.randrange(10000)
        auth._add(token,user)
        req={"token":token,"picklist_id":i}
        before=store.ms
        resp=strategy_fn(store,auth,req,cache)
        lat.append(store.ms-before)
        if resp!=expected(data,user,req): wrong+=1
    lat.sort()
    p95=lat[math.ceil(0.95*len(lat))-1]
    print("%-52s p95=%5.1f  median=%6.1f  min=%5.1f  max=%6.1f  wrong=%d"%(
        label,p95,lat[len(lat)//2],min(lat),max(lat),wrong))
    return p95

# Fully prewarm the catalog cache up front so EVERY request runs at steady state.
def prewarm_full(store, cache):
    # Load ALL catalog records once. (This is the deploy-time static data.)
    for k in range(N_SKU):
        cache["sku:%d"%k] = store._data.get("sku:%d"%k)
        cache["bin:%d"%k] = store._data.get("bin:%d"%k)
    for k in range(N_PICKER):
        cache["picker:%d"%k] = store._data.get("picker:%d"%k)

