    def h(store,auth,request,cache):
        user=auth.verify(request["token"])
        pl=store.get("picklist:%d"%request["picklist_id"])
        picker=cache.get("picker:%d"%pl["picker_id"])
        lines=[]; total=0
        for it in pl["items"]:
            sku=cache.get("sku:%d"%it["sku_id"]); binr=cache.get("bin:%d"%it["sku_id"])
            amount,name=compute(pl,picker,sku,binr,it)
            total+=amount; lines.append({"name":name,"amount":amount})
        return {"user":user,"picker":picker["name"],"lines":lines,"seconds_total":total}
    return h

cache={}
p95 = harness(mk_handler(cache), "C: FULLY prewarmed cache (steady-state floor)", prewarm_full)
print("=> C passes 90ms limit?", p95<=90)
