    student_name = student["name"] if student is not None else None
    keys, seen = [], set()
    for item in enrolment["items"]:
        for key in ("module:%d" % item["module_id"],
                    "scheme:%d" % item["module_id"]):
            if key not in seen:
                seen.add(key)
                keys.append(key)
    records = _REPLICA.get_many(store, keys) if keys else {}
    lines, total = [], 0
    for item in enrolment["items"]:
        mid = "module:%d" % item["module_id"]
